package awsapi
import("context";"sort";"strconv";"strings";"time";"github.com/aws/aws-sdk-go-v2/aws";"github.com/aws/aws-sdk-go-v2/service/costexplorer";"github.com/aws/aws-sdk-go-v2/service/costexplorer/types")
type CostRow struct{User string;Compute,Storage,Transfer,Other,Total float64}
type CostReport struct{Start,End string;Rows []CostRow;Total float64}
type CostReporter interface{UserCosts(context.Context,string,time.Time,time.Time)(CostReport,error)}
type CE struct{c *costexplorer.Client}
func NewCost(cfg aws.Config)*CE{return &CE{c:costexplorer.NewFromConfig(cfg)}}
func(e *CE)UserCosts(ctx,tag string,start,end time.Time)(CostReport,error){in:=&costexplorer.GetCostAndUsageInput{TimePeriod:&types.DateInterval{Start:aws.String(start.Format("2006-01-02")),End:aws.String(end.Format("2006-01-02"))},Granularity:types.GranularityMonthly,Metrics:[]string{"UnblendedCost"},GroupBy:[]types.GroupDefinition{{Type:types.GroupDefinitionTypeTag,Key:aws.String(tag)},{Type:types.GroupDefinitionTypeDimension,Key:aws.String("USAGE_TYPE")}}};out:=CostReport{Start:start.Format("2006-01-02"),End:end.Format("2006-01-02")};m:=map[string]*CostRow{};for{r,err:=e.c.GetCostAndUsage(ctx,in);if err!=nil{return out,err};for _,period:=range r.ResultsByTime{for _,g:=range period.Groups{if len(g.Keys)<2{continue};u:=strings.TrimPrefix(g.Keys[0],tag+"$");if u==""||u=="NoTagKey"||strings.Contains(u,"NoTagKey"){u="(未割当)"};v,_:=strconv.ParseFloat(aws.ToString(g.Metrics["UnblendedCost"].Amount),64);x:=m[u];if x==nil{x=&CostRow{User:u};m[u]=x};usage:=strings.ToLower(g.Keys[1]);switch{case strings.Contains(usage,"data transfer")||strings.Contains(usage,"datatransfer")||strings.Contains(usage,"bytes"):x.Transfer+=v;case strings.Contains(usage,"ebs")||strings.Contains(usage,"volume")||strings.Contains(usage,"storage")||strings.Contains(usage,"snapshot"):x.Storage+=v;case strings.Contains(usage,"boxusage")||strings.Contains(usage,"hostboxusage")||strings.Contains(usage,"instance"):x.Compute+=v;default:x.Other+=v};x.Total+=v;out.Total+=v}};if r.NextPageToken==nil||*r.NextPageToken==""{break};in.NextPageToken=r.NextPageToken};for _,x:=range m{out.Rows=append(out.Rows,*x)};sort.Slice(out.Rows,func(i,j int)bool{return out.Rows[i].Total>out.Rows[j].Total});return out,nil}
